CREATE TABLE IF NOT EXISTS blog_posts (id TEXT PRIMARY KEY,slug TEXT NOT NULL UNIQUE,title TEXT NOT NULL,excerpt TEXT NOT NULL,content TEXT NOT NULL,keywords TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED')),author_id TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,published_at TEXT);
CREATE INDEX IF NOT EXISTS blog_posts_status_date ON blog_posts(status,published_at DESC);
INSERT OR IGNORE INTO blog_posts(id,slug,title,excerpt,content,keywords,status,created_at,updated_at) VALUES
('seed-1','how-to-find-a-reliable-cleaner-in-harare','How to find a reliable cleaner in Harare','A practical checklist for choosing a trusted home cleaner in Harare without endless calls or guesswork.','Finding a cleaner should start with clarity: define the rooms, tasks, address and preferred time before comparing providers. Ask what identity and experience checks have been completed, agree the scope in writing and keep payment records.\n\nDetail is being built for this exact problem in Zimbabwe. Customers request a clean, compare offers from available cleaners, review profile information and keep job progress and payment records together. Join the Detail waitlist to hear when coverage reaches your Harare suburb.','reliable cleaner Harare, home cleaning Zimbabwe, Detail cleaning app','DRAFT','2026-09-22T00:00:00Z','2026-09-22T00:00:00Z'),
('seed-2','how-much-does-house-cleaning-cost-in-zimbabwe','How much does house cleaning cost in Zimbabwe?','Understand the factors that affect Zimbabwe house-cleaning quotes and how to compare cleaner offers fairly.','There is no single fair price for every home clean. Cost depends on floor area, number of rooms, current condition, deep-clean tasks, supplies, travel distance and urgency. A useful quote should state exactly what is included.\n\nDetail is designed to let customers describe the job once and compare transparent bids from available cleaners. That can reduce time spent phoning around while helping cleaners price the real scope of work. Final availability and prices will vary by area.','house cleaning prices Zimbabwe, cleaners Harare, cleaning quotes','DRAFT','2026-09-22T00:00:00Z','2026-09-22T00:00:00Z'),
('seed-3','what-is-included-in-a-deep-house-clean','What is included in a deep house clean?','Use this room-by-room guide to set expectations before booking a deep clean.','A deep clean normally goes beyond routine dusting and floors. It may include reachable fittings, skirting, cupboard fronts, bathroom build-up, kitchen grease and detailed attention to corners. Inside appliances, high exterior windows and hazardous waste should be agreed separately.\n\nClear scope prevents disputes. Detail lets a customer describe the cleaning problem, receive offers and retain the agreed job information in one place before work begins.','deep cleaning checklist, house cleaning app Zimbabwe, Detail','DRAFT','2026-09-22T00:00:00Z','2026-09-22T00:00:00Z'),
('seed-4','how-to-clean-a-car-interior-after-spills','How to clean a car interior after spills','Act quickly and safely after drink, food or muddy-water spills in a vehicle interior.','Blot a fresh spill rather than rubbing it deeper. Check the care instructions for leather, fabric or trim, test products in a hidden spot and avoid soaking seats because trapped moisture can create odour or mould. Persistent stains may need specialist extraction.\n\nDetail plans to connect Zimbabwe customers with vehicle-detailing providers, allowing them to explain the stain, location and timing and compare suitable offers.','car interior cleaning Zimbabwe, mobile car detailing Harare, spill removal','DRAFT','2026-09-22T00:00:00Z','2026-09-22T00:00:00Z'),
('seed-5','moving-house-cleaning-checklist-zimbabwe','A moving-house cleaning checklist for Zimbabwe','A straightforward plan for move-in and move-out cleaning, from utilities to final photos.','Work from the top of each room down, leaving floors until last. Empty cupboards, remove loose rubbish, clean kitchens and bathrooms, check walls and fittings, then photograph the completed condition. Confirm water and electricity will be available for the cleaner.\n\nFor customers who need help, Detail is building a coordinated way to request move-related cleaning, compare bids and follow completion without managing multiple conversations.','move out cleaning Zimbabwe, move in clean Harare, cleaning checklist','DRAFT','2026-09-22T00:00:00Z','2026-09-22T00:00:00Z'),
('seed-6','how-to-book-office-cleaning-without-disrupting-work','How to arrange office cleaning without disrupting work','Plan access, security, timing and scope for a smoother commercial clean.','Start by identifying high-traffic areas, sensitive equipment, access rules and tasks that must happen outside working hours. Nominate one contact, document locked or excluded spaces and decide how completion will be checked.\n\nDetail is intended to keep office-cleaning requests, cleaner offers, timing and job progress visible in one workflow. Businesses can join the waitlist while service coverage is prepared.','office cleaning Zimbabwe, commercial cleaners Harare, book a cleaner','DRAFT','2026-09-22T00:00:00Z','2026-09-22T00:00:00Z');
